    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long a = scanner.nextLong();
        long c = scanner.nextLong();

        long[] x = new long[105];
        long[] y = new long[105];
        int i = 1;

        while (a > 0 || c > 0) {
            x[i] = a % 3;
            a /= 3;
            y[i] = c % 3;
            c /= 3;
            i++;
        }

        long b = 0;
        for (int j = i - 1; j >= 1; j--) {
            b = b * 3 + ((y[j] - x[j] + 3) % 3);
        }

        System.out.println(b);
    }
}

